// TH14 Stage 5 midboss wave: 40 Phantom03 per side.
// Source st05.ecl.txt: MainSub04:736-748 (left line), MainSub04b:750-764 (right line,
// async, 40-frame cadence both), Phantom03:1182-1205 (enemy), Phantom03_at:1207-1248
// (10 volleys). Card frame 0 = source 736; source attack runs after OPENING_BUFFER.

const TIME_LIMIT: int = 3224;
const OPENING_BUFFER: int = 120;

// TH14 native etSprite type 10 -> same catalog slot (see touhou-bullets.ecl).
const TH14_SHARD: int = 512;
const SHARD_COLOR: int = 6;

// Source per-volley EX: slot1 VELTIME a=120, r=RANDF*0.3, s sentinel = spawn angle;
// slot2 ACCEL a=120, r=0.02, s=pi/2 literal. VELTIME's saved direction and ACCEL's
// vector are both fixed at effect entry, so their per-tick sum is one constant
// Cartesian gravity. delta = (RANDF*0.3 - 2.5) / 120; both end after 120 frames.
xformdef SHARD_EX(delta: fx) {
    @120 set_gravity(at_spawn(delta * cos($self_angle)),
                     at_spawn(delta * sin($self_angle) + 0.02fx));
    set_gravity(0fx, 0fx);
}

// st05.ecl.txt:1207 Phantom03_at. etAim mode1 is a fixed-direction fan, so the
// emitted base angle is the enemy's own ABS angle plus a per-volley random offset.
async sub phantom03_at() {
    var n: int = 1;
    var interval: int = 30;
    var rank: int = global(GVAR_RANK);
    if rank == 2 { n = 2; }
    if rank >= 3 { n = 3; }
    if rank == 0 { interval = 60; }
    for volley in 0..10 {
        // RANDF*0.3 and RANDF2*20deg are sampled once per volley at EX/angle config.
        var target_speed: fx = ((rand(19661) as fx) / 256fx) / 256fx;
        var delta: fx = (target_speed - 2.5fx) / 120fx;
        var off: int = rand(7282) - 3641;
        var base: angle = $self_angle + (off as angle);
        if n == 1 {
            _ = fire(TH14_SHARD, SHARD_COLOR, $self_x, $self_y, 2.5fx, base,
                     SHARD_EX(delta), none);
        } else if n == 2 {
            _ = fire(TH14_SHARD, SHARD_COLOR, $self_x, $self_y, 2.5fx, base + 10deg,
                     SHARD_EX(delta), none);
            _ = fire(TH14_SHARD, SHARD_COLOR, $self_x, $self_y, 2.5fx, base - 10deg,
                     SHARD_EX(delta), none);
        } else {
            _ = fire(TH14_SHARD, SHARD_COLOR, $self_x, $self_y, 2.5fx, base,
                     SHARD_EX(delta), none);
            _ = fire(TH14_SHARD, SHARD_COLOR, $self_x, $self_y, 2.5fx, base - 20deg,
                     SHARD_EX(delta), none);
            _ = fire(TH14_SHARD, SHARD_COLOR, $self_x, $self_y, 2.5fx, base + 20deg,
                     SHARD_EX(delta), none);
        }
        wait(interval);
    }
}

// st05.ecl.txt:1182 Phantom03. side 0 = enmCreateF line (no mirror), side 1 =
// enmCreateMF line (child mirror set). Mirrored angles are written out explicitly
// (mirror reflects angle across the vertical axis); bullet bases read $self_angle,
// i.e. the already-mirrored actual velocity direction.
async sub phantom03(side: int) {
    set_invuln(65535);
    set_hurtbox(14fx);   // setHurtbox(28,28): circle branch uses first*0.5
    set_hitbox(8fx);     // setHitbox(16,16): circle branch uses first*0.5
    if side == 0 {
        move_vel(0, 45deg, 4fx, EASE_LINEAR);      // moveVel(pi/4, 4.0)
        move_vel(30, 0deg, 0fx, EASE_LINEAR);      // moveVelTime(30,0,0,0)
    } else {
        move_vel(0, 135deg, 4fx, EASE_LINEAR);
        move_vel(30, 180deg, 0fx, EASE_LINEAR);
    }
    wait(30);
    if side == 0 {
        move_vel(0, -11.25deg, 0fx, EASE_LINEAR);  // moveVel(-0.19634955, 0)
    } else {
        move_vel(0, 191.25deg, 0fx, EASE_LINEAR);
    }
    move_speed(240, 2fx, EASE_QUAD_IN);            // moveSpeedTime(240,1,2.0)
    // moveCircleRel(RANDRAD, 1deg/frame, radius ~0.196px, d=0): REL layer only,
    // sub-pixel (<=0.2px) wobble, left out under the circular-motion tolerance.
    spawn phantom03_at();
    wait(60);
    loop { wait(1000); }
}

// Source two parallel lines share the same cadence; each iteration spawns both
// sides in the source order (MainSub04 then MainSub04b). F/MF boss gate omitted
// as approved. Positions: x = -/+(192 + RANDF*32), y = 96 + RANDF*64.
async sub pattern() {
    wait(OPENING_BUFFER);
    for i in 0..40 {
        var xl: fx = -192fx - (rand(2048) as fx) / 64fx;
        var yl: fx = 96fx + (rand(4096) as fx) / 64fx;
        _ = spawn_enemy(xl, yl, 100, 0, 1000, 0, phantom03(0));
        var xr: fx = 192fx + (rand(2048) as fx) / 64fx;
        var yr: fx = 96fx + (rand(4096) as fx) / 64fx;
        _ = spawn_enemy(xr, yr, 100, 0, 1000, 0, phantom03(1));
        wait(40);
    }
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
